#!/usr/bin/perl
# Differential fuzzer: C++ reference vs Rust port.
# Compares stdout bytes, stderr bytes and exit status (incl. signal) exactly.
use strict; use warnings;
use POSIX qw(WIFSIGNALED WTERMSIG WIFEXITED WEXITSTATUS);

my $CPP  = "/workspace/dataset/test15_executable";
my $RUST = "/output/test15";
my $TMP  = "/tmp/probe/run";
mkdir $TMP unless -d $TMP;

sub slurp { my ($f)=@_; open(my $fh,'<',$f) or return ''; binmode $fh; local $/; my $d=<$fh>; close $fh; return defined $d ? $d : ''; }

sub runbin {
    my ($bin,@args)=@_;
    my $o="$TMP/o.$$"; my $e="$TMP/e.$$";
    my $pid=fork(); die "fork: $!" unless defined $pid;
    if ($pid==0) {
        open(STDOUT,'>',$o) or exit 127; binmode STDOUT;
        open(STDERR,'>',$e) or exit 127; binmode STDERR;
        exec {$bin} $bin, @args;
        exit 127;
    }
    waitpid($pid,0);
    my $st=$?;
    my $code = WIFSIGNALED($st) ? 128+WTERMSIG($st) : WEXITSTATUS($st);
    return (slurp($o), slurp($e), $code);
}

my ($npass,$nfail)=(0,0);
my @FAIL; my %seen;

sub diffcase {
    my @args=@_;
    my $key=join("\x00", scalar(@args), @args);
    return if $seen{$key}++;
    my ($co,$ce,$cx)=runbin($CPP,@args);
    my ($ro,$re,$rx)=runbin($RUST,@args);
    if ($co eq $ro && $ce eq $re && $cx==$rx) { $npass++; return 1; }
    $nfail++;
    if (@FAIL < 40) {
        push @FAIL, { args=>[@args],
                      c=>[unpack("H*",$co), unpack("H*",$ce), $cx],
                      r=>[unpack("H*",$ro), unpack("H*",$re), $rx] };
    }
    return 0;
}

# ---------- random arg generation ----------
my @HOT = split //, '____::::ssssaaiittTAISN0123456789-./ nabcdefgABCDEFGHIJKLMNOPQRSTUVWXYZ';
my @ALL = map { chr } 32..126;
my @TOK = qw(equipment information rice money species series fish sheep jeans
             police news oxen octopi viri mice lice data ta ia s S News NEWS
             Module a b goodnews miniseries subspecies myjeans slice twice
             cacti alumni boxen status alias this ss);
push @TOK, ('', ':', '::', '_', '__', 'a:b', 'A_B', '_A', 'x:', ':x');

sub rand_arg {
    my $n=int(rand(41));
    my $s='';
    for (1..$n) {
        my $r=rand();
        if    ($r<0.60) { $s .= $HOT[int(rand(scalar @HOT))] }
        else            { $s .= $ALL[int(rand(scalar @ALL))] }
    }
    if (rand() < 0.12) { $s = $TOK[int(rand(scalar @TOK))] . $s }
    if (rand() < 0.06) { $s = $TOK[int(rand(scalar @TOK))] }
